package com.mikeyphw.hooklab.termux;
import org.junit.Test;
import static org.junit.Assert.*;
public final class TermuxCommandPolicyTest {
 @Test public void exactMultilineArguments(){String s="printf '%s\\n' 'a,b'\n  echo '💡'\n";for(String sh:new String[]{"zsh","bash","sh","python3"}){String[] a=TermuxCommandPolicy.arguments(s,sh);assertEquals(7,a.length);assertEquals("-c",a[0]);assertEquals("hooklab",a[2]);assertEquals(s,a[3]);assertEquals(sh,a[4]);assertFalse(a[1].contains(s));assertTrue(a[1].contains("export NOART=1"));assertTrue(a[6].contains("builtin eval"));}}
 @Test public void requestFreshness(){String id="01234567-89ab-4cde-8fab-0123456789ab";assertTrue(TermuxCommandPolicy.freshRequest(id,100,100));assertTrue(TermuxCommandPolicy.freshRequest(id,100,15100));assertFalse(TermuxCommandPolicy.freshRequest(id,100,15101));assertFalse(TermuxCommandPolicy.freshRequest(id,101,100));assertFalse(TermuxCommandPolicy.freshRequest("not-an-id",100,100));assertFalse(TermuxCommandPolicy.freshRequest(null,100,100));assertFalse(TermuxCommandPolicy.freshRequest(id,-1,100));}
 @Test public void wallClockWindow(){assertTrue(TermuxCommandPolicy.freshWall(100,15100));assertFalse(TermuxCommandPolicy.freshWall(100,15101));assertFalse(TermuxCommandPolicy.freshWall(100,99));assertFalse(TermuxCommandPolicy.freshWall(0,0));}
 @Test public void directoryRules(){assertEquals(TermuxCommandPolicy.HOME,TermuxCommandPolicy.checkedWorkingDirectory("~"));assertEquals(TermuxCommandPolicy.HOME+"/Code",TermuxCommandPolicy.checkedWorkingDirectory("~/Code"));for(String s:new String[]{"~/../other","~/a//b","/data/data/com.termux/files/home2","/sdcard/Download"}){try{TermuxCommandPolicy.checkedWorkingDirectory(s);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void rejectsNonReviewedInputs(){for(String s:new String[]{""," \n","a\u0000b","a\u202eb","a\ud800","x".repeat(TermuxCommandPolicy.MAX_BYTES+1)}){try{TermuxCommandPolicy.checkedCommand(s);fail();}catch(IllegalArgumentException expected){}}try{TermuxCommandPolicy.checkedShell("/system/bin/su");fail();}catch(IllegalArgumentException expected){}}
}
